import { HttpContextToken, HttpInterceptorFn } from '@angular/common/http';
import { inject } from '@angular/core';
import { Session } from './session';

/** Marks a sheet request that reads the live sheet whatever date the screen shows it as of. */
export const LIVE = new HttpContextToken<boolean>(() => false);

/** Names the date the screen shows the sheet as of (X-As-Of) on every sheet request while one is set. */
export const asOfInterceptor: HttpInterceptorFn = (req, next) => {
  const asOf = inject(Session).asOf();
  if (asOf === null || req.context.get(LIVE) || !req.url.startsWith('/api/sheets/')) return next(req);
  return next(req.clone({ setHeaders: { 'X-As-Of': asOf } }));
};
import { HttpClient } from '@angular/common/http';
import { Injectable, computed, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

/** The locales a user may choose; en unless chosen. */
export const LOCALES = ['en', 'de'] as const;
export type Locale = (typeof LOCALES)[number];

interface SheetView {
  id: string;
  today: string;
  archived: boolean;
  /** The id of the sheet's parent sheet; null when it has none. */
  parent: string | null;
}

// The signed-in user and the active sheet. Every request after sign-in names the user in X-User.
@Injectable({ providedIn: 'root' })
export class Session {
  private readonly http = inject(HttpClient);

  readonly user = signal<string | null>(null);
  /** The signed-in user's locale, saved per user: how the screen shows them figures. */
  readonly locale = signal<Locale>('en');
  readonly sheet = signal<string | null>(null);
  /** The active sheet's own today (yyyy-mm-dd), whatever date the screen shows it as of. */
  private readonly sheetToday = signal<string | null>(null);
  /**
   * The date this screen shows the sheet as of (yyyy-mm-dd), or null for the sheet as it stands. While set,
   * every read is of the sheet as it stood at the end of that date and every change is refused.
   */
  readonly asOf = signal<string | null>(null);
  /** The active sheet's today (yyyy-mm-dd): every date the screen decides on or defaults to; the as-of date while set. */
  readonly today = computed(() => this.asOf() ?? this.sheetToday());
  /** Whether the active sheet is archived: it stays visible and every change to it is refused. */
  readonly archived = signal(false);
  /** The id of the active sheet's parent sheet, as it stands; null when it has none. */
  readonly parent = signal<string | null>(null);
  /** The id of the last clone of the active sheet made from this screen; null before any. */
  readonly clonedTo = signal<string | null>(null);
  /** Bumped on every sheet load, so what is shown for the sheet is re-read even for the same id. */
  readonly loads = signal(0);

  async signIn(name: string): Promise<void> {
    const res = await firstValueFrom(this.http.post<{ name: string; locale: Locale }>('/api/signin', { name }));
    this.sheet.set(null);
    this.sheetToday.set(null);
    this.asOf.set(null);
    this.archived.set(false);
    this.parent.set(null);
    this.clonedTo.set(null);
    this.loads.update((n) => n + 1);
    this.locale.set(res.locale);
    this.user.set(res.name);
  }

  /** Save the signed-in user's locale. */
  async setLocale(locale: Locale): Promise<void> {
    const res = await firstValueFrom(
      this.http.put<{ locale: Locale }>('/api/me/locale', { locale }, {
        headers: { 'X-User': this.user() ?? '' },
      }),
    );
    this.locale.set(res.locale);
  }

  async loadSheet(id: string): Promise<void> {
    const res = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/load`, null, {
        headers: { 'X-User': this.user() ?? '' },
      }),
    );
    this.sheet.set(res.id);
    this.sheetToday.set(res.today);
    this.archived.set(res.archived);
    this.parent.set(res.parent);
    this.clonedTo.set(null);
    if (this.asOf() !== null) await this.readShown(res.id);
    this.loads.update((n) => n + 1);
  }

  /** Show the active sheet as of a date (yyyy-mm-dd), or as it stands (null): everything shown is re-read. */
  async setAsOf(date: string | null): Promise<void> {
    this.asOf.set(date);
    const id = this.sheet();
    if (id) await this.readShown(id);
    this.loads.update((n) => n + 1);
  }

  /** Re-read whether the sheet is archived, as it is shown (as of the as-of date while one is set). */
  private async readShown(id: string): Promise<void> {
    const res = await firstValueFrom(this.http.get<SheetView>(`/api/sheets/${encodeURIComponent(id)}`));
    if (this.sheet() === res.id) this.archived.set(res.archived);
  }

  async setToday(today: string): Promise<void> {
    const id = this.sheet();
    if (!id) return;
    const res = await firstValueFrom(
      this.http.put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today }, {
        headers: { 'X-User': this.user() ?? '' },
      }),
    );
    if (this.sheet() === res.id) this.sheetToday.set(res.today);
  }

  async archive(): Promise<void> {
    const id = this.sheet();
    if (!id) return;
    const res = await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/archive`, null, {
        headers: { 'X-User': this.user() ?? '' },
      }),
    );
    if (this.sheet() === res.id) this.archived.set(res.archived);
  }

  /** Clone the active sheet to another id, which must never have been used. */
  async cloneTo(to: string): Promise<void> {
    const id = this.sheet();
    if (!id) return;
    await firstValueFrom(
      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/clone`, { to }, {
        headers: { 'X-User': this.user() ?? '' },
      }),
    );
    if (this.sheet() === id) this.clonedTo.set(to);
  }
}
import { Pipe, PipeTransform, inject } from '@angular/core';
import { Session } from './session';

/** A figure as the server sends it: digits, a dot, two decimals. */
const FIGURE = /^(-?)(\d+)\.(\d{2})$/;

/**
 * Shows a figure (an amount, total, rate, share or cut with two decimals) in the signed-in user's locale:
 * under de as 1.234,56, under en as it comes. Anything that is not such a figure is shown as it is.
 * Impure, as it reads the user's locale, which may change while the value does not.
 */
@Pipe({ name: 'figure', pure: false })
export class FigurePipe implements PipeTransform {
  private readonly session = inject(Session);

  transform<T>(value: T): T | string {
    return formatFigure(value, this.session.locale());
  }
}

export function formatFigure<T>(value: T, locale: string): T | string {
  if (locale !== 'de' || typeof value !== 'string') return value;
  const m = FIGURE.exec(value);
  if (!m) return value;
  return `${m[1]}${m[2].replace(/\B(?=(\d{3})+$)/g, '.')},${m[3]}`;
}
import { Component, inject, linkedSignal, signal } from '@angular/core';
import { LOCALES, Locale, Session } from '../../core/session';
import { People } from '../people/people';

// The one screen: sign in by name, then load a sheet by id.
@Component({
  selector: 'app-home',
  imports: [People],
  template: `
    @if (session.user(); as user) {
      <section aria-label="Session">
        <p>Signed in as <strong data-testid="current-user">{{ user }}</strong></p>
        <form (submit)="saveLocale($event)" aria-label="Locale">
          <p>Locale <strong data-testid="user-locale-current">{{ session.locale() }}</strong></p>
          <label for="user-locale">Show figures as</label>
          <select
            id="user-locale"
            data-testid="user-locale"
            [value]="localeInput()"
            (change)="localeInput.set($any(value($event))); localeError.set('')"
          >
            @for (l of locales; track l) {
              <option [value]="l" [selected]="l === localeInput()">{{ l }}</option>
            }
          </select>
          <button type="submit" data-testid="user-locale-save">Save locale</button>
          @if (localeError()) {
            <p role="alert" data-testid="user-locale-error">{{ localeError() }}</p>
          }
        </form>
        <form (submit)="load($event)">
          <label for="sheet-id">Sheet id</label>
          <input
            id="sheet-id"
            data-testid="sheet-id-input"
            [value]="sheetInput()"
            (input)="sheetInput.set(value($event)); sheetError.set('')"
          />
          <button type="submit" data-testid="sheet-load">Load</button>
          @if (sheetError()) {
            <p role="alert" data-testid="sheet-error">{{ sheetError() }}</p>
          }
        </form>
        @if (session.sheet(); as sheet) {
          <p>Sheet <strong data-testid="sheet-current-id">{{ sheet }}</strong></p>
          <form (submit)="saveToday($event)" aria-label="Sheet today">
            <p>Today <strong data-testid="sheet-today">{{ session.today() }}</strong></p>
            <label for="sheet-today-input">Set today</label>
            <input
              id="sheet-today-input"
              type="date"
              data-testid="sheet-today-input"
              [value]="todayInput()"
              (input)="todayInput.set(value($event)); sheetError.set('')"
            />
            <button type="submit" data-testid="sheet-today-save">Set today</button>
          </form>
          <form (submit)="setAsOf($event)" aria-label="Sheet as of">
            <p>As of <strong data-testid="sheet-asof">{{ session.asOf() ?? '' }}</strong></p>
            <label for="asof-date">Show the sheet as of</label>
            <input
              id="asof-date"
              type="date"
              data-testid="asof-date"
              [value]="asOfInput()"
              (input)="asOfInput.set(value($event)); sheetError.set('')"
            />
            <button type="submit" data-testid="asof-set">Set as of</button>
            <button type="button" data-testid="asof-clear" (click)="clearAsOf()">Clear as of</button>
          </form>
          <p>Parent sheet <strong data-testid="sheet-parent">{{ session.parent() ?? '' }}</strong></p>
          <p>
            Archived <strong data-testid="sheet-archived">{{ session.archived() ? 'yes' : 'no' }}</strong>
            <button type="button" data-testid="sheet-archive" (click)="archive()">Archive sheet</button>
          </p>
          <form (submit)="cloneTo($event)" aria-label="Clone sheet">
            <label for="sheet-clone-to">Clone to sheet id</label>
            <input
              id="sheet-clone-to"
              data-testid="sheet-clone-to"
              [value]="cloneInput()"
              (input)="cloneInput.set(value($event)); sheetError.set('')"
            />
            <button type="submit" data-testid="sheet-clone">Clone sheet</button>
            <p>Last clone made <strong data-testid="sheet-cloned-to">{{ session.clonedTo() ?? '' }}</strong></p>
          </form>
          <app-people />
        }
      </section>
    } @else {
      <form (submit)="signIn($event)" aria-label="Sign in">
        <label for="signin-name">Name</label>
        <input
          id="signin-name"
          data-testid="signin-name"
          [value]="nameInput()"
          (input)="nameInput.set(value($event)); signinError.set('')"
        />
        <button type="submit" data-testid="signin-submit">Sign in</button>
        @if (signinError()) {
          <p role="alert" data-testid="signin-error">{{ signinError() }}</p>
        }
      </form>
    }
  `,
})
export class Home {
  protected readonly session = inject(Session);
  protected readonly nameInput = signal('');
  protected readonly sheetInput = signal('');
  protected readonly signinError = signal('');
  protected readonly sheetError = signal('');
  protected readonly todayInput = signal('');
  protected readonly asOfInput = signal('');
  protected readonly cloneInput = signal('');
  protected readonly locales = LOCALES;
  /** The locale chosen in the select; it follows the user's saved locale until changed. */
  protected readonly localeInput = linkedSignal<Locale>(() => this.session.locale());
  protected readonly localeError = signal('');
  /** A today change, archive or clone still waiting for its answer: another press meanwhile is ignored. */
  private busy = false;

  protected value(e: Event): string {
    return (e.target as HTMLInputElement).value;
  }

  protected async signIn(e: Event): Promise<void> {
    e.preventDefault();
    this.signinError.set('');
    const name = this.nameInput().trim();
    if (!name) {
      this.signinError.set('Enter a name.');
      return;
    }
    try {
      await this.session.signIn(name);
    } catch {
      this.signinError.set('Could not sign in.');
    }
  }

  protected async saveLocale(e: Event): Promise<void> {
    e.preventDefault();
    this.localeError.set('');
    try {
      await this.session.setLocale(this.localeInput());
    } catch {
      this.localeError.set('Could not save the locale.');
    }
  }

  protected async load(e: Event): Promise<void> {
    e.preventDefault();
    this.sheetError.set('');
    const id = this.sheetInput().trim();
    if (!id) {
      this.sheetError.set('Enter a sheet id.');
      return;
    }
    try {
      await this.session.loadSheet(id);
    } catch {
      this.sheetError.set('Could not load the sheet.');
    }
  }

  protected async archive(): Promise<void> {
    if (this.busy) return;
    this.sheetError.set('');
    this.busy = true;
    try {
      await this.session.archive();
    } catch {
      this.sheetError.set('Could not archive the sheet.');
    } finally {
      this.busy = false;
    }
  }

  protected async cloneTo(e: Event): Promise<void> {
    e.preventDefault();
    if (this.busy) return;
    this.sheetError.set('');
    const to = this.cloneInput().trim();
    if (!to) {
      this.sheetError.set('Enter a sheet id to clone to.');
      return;
    }
    this.busy = true;
    try {
      await this.session.cloneTo(to);
    } catch {
      this.sheetError.set('Could not clone the sheet.');
    } finally {
      this.busy = false;
    }
  }

  protected async setAsOf(e: Event): Promise<void> {
    e.preventDefault();
    this.sheetError.set('');
    const date = this.asOfInput().trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      this.sheetError.set('Enter a date to show the sheet as of.');
      return;
    }
    await this.showAsOf(date);
  }

  protected async clearAsOf(): Promise<void> {
    this.sheetError.set('');
    await this.showAsOf(null);
  }

  private async showAsOf(date: string | null): Promise<void> {
    try {
      await this.session.setAsOf(date);
    } catch {
      this.sheetError.set('Could not show the sheet as of that date.');
    }
  }

  protected async saveToday(e: Event): Promise<void> {
    e.preventDefault();
    if (this.busy) return;
    this.sheetError.set('');
    const today = this.todayInput().trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(today)) {
      this.sheetError.set('Enter a date for today.');
      return;
    }
    this.busy = true;
    try {
      await this.session.setToday(today);
    } catch {
      this.sheetError.set('Could not change today.');
    } finally {
      this.busy = false;
    }
  }
}

